package com.resumeanalyzer.entity;
import jakarta.persistence.*; import lombok.*; import org.hibernate.annotations.CreationTimestamp; import java.time.Instant; import java.util.ArrayList; import java.util.List;
@Entity @Table(name="resumes",indexes={@Index(name="idx_resumes_user",columnList="user_id"),@Index(name="idx_resumes_uploaded",columnList="uploaded_at")}) @Getter @Setter @NoArgsConstructor @Builder @AllArgsConstructor
public class Resume { @Id @GeneratedValue(strategy=GenerationType.IDENTITY) private Long id; @ManyToOne(fetch=FetchType.LAZY,optional=false) @JoinColumn(name="user_id",nullable=false) private User user; @Column(name="file_name",nullable=false,length=255) private String fileName; @Column(name="storage_key",nullable=false,length=512,unique=true) private String storageKey; @Lob @Column(name="raw_text",nullable=false,columnDefinition="LONGTEXT") private String rawText; @CreationTimestamp @Column(name="uploaded_at",nullable=false,updatable=false) private Instant uploadedAt; @OneToMany(mappedBy="resume",cascade=CascadeType.ALL,orphanRemoval=true) @Builder.Default private List<AnalysisResult> analysisResults=new ArrayList<>(); }
